query:
query issueEventsAndAssociatedObjectsByLocationBreakdown(
  $details: IssueDetails!
  $dimension: LocationBreakdownDimension!
) {
  issueEventsAndAssociatedObjectsByLocationBreakdown(
    details: $details
    dimension: $dimension
  ) {
    label
    items {
      label
      value
    }
  }
}
